INSERT INTO public.questions (id, department_id, course_id, module_id, course_outcome_id, k_level_id, question_type_id, marks_id, mark_value, question_text) VALUES
('15151515-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', 'c1111111-1111-1111-1111-111111111111', 'b1111111-1111-1111-1111-111111111111', 'ca111111-1111-1111-1111-111111111111', 'e3333333-3333-3333-3333-333333333333', 'd3333333-3333-3333-3333-333333333333', 'e0000015-0000-0000-0000-000000000015', 15, '(a) Explain the ISO/OSI 7-Layer Reference Model with neat diagrams and detail the exact functions of each layer.'),
